import type { AddressErrors, DeliveryAddress } from './types';

const PHONE_PATTERN = /^\+?[0-9()\- ]{7,20}$/;

export function validateAddress(address: DeliveryAddress): AddressErrors {
  const errors: AddressErrors = {};

  if (!address.fullName.trim()) {
    errors.fullName = 'Enter your full name';
  }

  if (!address.phone.trim()) {
    errors.phone = 'Enter a phone number';
  } else if (!PHONE_PATTERN.test(address.phone.trim())) {
    errors.phone = 'Enter a valid phone number';
  }

  if (!address.city.trim()) {
    errors.city = 'Enter your city';
  }

  if (!address.street.trim()) {
    errors.street = 'Enter your street address';
  }

  if (!address.postalCode.trim()) {
    errors.postalCode = 'Enter a postal code';
  }

  return errors;
}
