```tsx
import React, { useMemo, useState } from 'react';
import type { AddressErrors, CheckoutScreenProps, DeliveryAddress } from './types';
import { validateAddress } from './validateAddress';
import './CheckoutScreen.css';

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: '',
  phone: '',
  city: '',
  street: '',
  apartment: '',
  postalCode: '',
  comment: '',
};

const FREE_DELIVERY_THRESHOLD = 50;
const FLAT_DELIVERY_FEE = 5;

function formatPrice(value: number, currency: string): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency,
    minimumFractionDigits: 2,
  }).format(value);
}

export default function CheckoutScreen({
  cartItems,
  currency = 'USD',
  onBack,
  onSubmit,
}: CheckoutScreenProps) {
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [errors, setErrors] = useState<AddressErrors>({});
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);

  const subtotal = useMemo(
    () => cartItems.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [cartItems]
  );
  const deliveryFee = subtotal === 0 || subtotal >= FREE_DELIVERY_THRESHOLD ? 0 : FLAT_DELIVERY_FEE;
  const total = subtotal + deliveryFee;
  const isCartEmpty = cartItems.length === 0;

  function handleFieldChange<K extends keyof DeliveryAddress>(field: K, value: string) {
    setAddress((prev) => ({ ...prev, [field]: value }));
    setErrors((prev) => ({ ...prev, [field]: undefined }));
  }

  async function handlePay() {
    if (isCartEmpty || submitting) return;

    const validationErrors = validateAddress(address);
    if (Object.keys(validationErrors).length > 0) {
      setErrors(validationErrors);
      window.Telegram?.WebApp.HapticFeedback?.notificationOccurred('error');
      return;
    }

    setSubmitError(null);
    setSubmitting(true);
    try {
      await onSubmit(address);
      window.Telegram?.WebApp.HapticFeedback?.notificationOccurred('success');
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Payment failed. Please try again.';
      setSubmitError(message);
      window.Telegram?.WebApp.HapticFeedback?.notificationOccurred('error');
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className="checkout">
      <header className="checkout__header">
        <button
          type="button"
          className="checkout__back-button"
          onClick={onBack}
          aria-label="Back to cart"
        >
          <svg
            width="20"
            height="20"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
            aria-hidden="true"
          >
            <path d="M15 18l-6-6 6-6" />
          </svg>
        </button>
        <h1 className="checkout__title">Checkout</h1>
      </header>

      <main className="checkout__content">
        <section className="checkout__section" aria-labelledby="cart-heading">
          <h2 id="cart-heading" className="checkout__section-title">
            Order ({cartItems.length})
          </h2>

          {isCartEmpty ? (
            <p className="checkout__empty">Your cart is empty.</p>
          ) : (
            <ul className="cart-list">
              {cartItems.map((item) => (
                <li key={item.id} className="cart-item">
                  <div className="cart-item__image">
                    {item.imageUrl ? (
                      <img src={item.imageUrl} alt={item.name} />
                    ) : (
                      <div className="cart-item__image-placeholder" aria-hidden="true" />
                    )}
                  </div>
                  <div className="cart-item__info">
                    <span className="cart-item__name">{item.name}</span>
                    <span className="cart-item__meta">
                      {item.quantity} × {formatPrice(item.price, currency)}
                    </span>
                  </div>
                  <span className="cart-item__total">
                    {formatPrice(item.price * item.quantity, currency)}
                  </span>
                </li>
              ))}
            </ul>
          )}

          {!isCartEmpty && (
            <div className="checkout__summary">
              <div className="checkout__summary-row">
                <span>Subtotal</span>
                <span>{formatPrice(subtotal, currency)}</span>
              </div>
              <div className="checkout__summary-row">
                <span>Delivery</span>
                <span>{deliveryFee === 0 ? 'Free' : formatPrice(deliveryFee, currency)}</span>
              </div>
              <div className="checkout__summary-row checkout__summary-row--total">
                <span>Total</span>
                <span>{formatPrice(total, currency)}</span>
              </div>
            </div>
          )}
        </section>

        <section className="checkout__section" aria-labelledby="address-heading">
          <h2 id="address-heading" className="checkout__section-title">
            Delivery address
          </h2>

          <form className="address-form" noValidate>
            <div className="form-field">
              <label htmlFor="fullName">Full name</label>
              <input
                id="fullName"
                type="text"
                autoComplete="name"
                value={address.fullName}
                onChange={(e) => handleFieldChange('fullName', e.target.value)}
                className={errors.fullName ? 'form-field__input--error' : undefined}
              />
              {errors.fullName && <span className="form-field__error">{errors.fullName}</span>}
            </div>

            <div className="form-field">
              <label htmlFor="phone">Phone number</label>
              <input
                id="phone"
                type="tel"
                autoComplete="tel"
                value={address.phone}
                onChange={(e) => handleFieldChange('phone', e.target.value)}
                className={errors.phone ? 'form-field__input--error' : undefined}
              />
              {errors.phone && <span className="form-field__error">{errors.phone}</span>}
            </div>

            <div className="form-row">
              <div className="form-field">
                <label htmlFor="city">City</label>
                <input
                  id="city"
                  type="text"
                  autoComplete="address-level2"
                  value={address.city}
                  onChange={(e) => handleFieldChange('city', e.target.value)}
                  className={errors.city ? 'form-field__input--error' : undefined}
                />
                {errors.city && <span className="form-field__error">{errors.city}</span>}
              </div>

              <div className="form-field">
                <label htmlFor="postalCode">Postal code</label>
                <input
                  id="postalCode"
                  type="text"
                  autoComplete="postal-code"
                  value={address.postalCode}
                  onChange={(e) => handleFieldChange('postalCode', e.target.value)}
                  className={errors.postalCode ? 'form-field__input--error' : undefined}
                />
                {errors.postalCode && (
                  <span className="form-field__error">{errors.postalCode}</span>
                )}
              </div>
            </div>

            <div className="form-field">
              <label htmlFor="street">Street address</label>
              <input
                id="street"
                type="text"
                autoComplete="street-address"
                value={address.street}
                onChange={(e) => handleFieldChange('street', e.target.value)}
                className={errors.street ? 'form-field__input--error' : undefined}
              />
              {errors.street && <span className="form-field__error">{errors.street}</span>}
            </div>

            <div className="form-field">
              <label htmlFor="apartment">Apartment / suite (optional)</label>
              <input
                id="apartment"
                type="text"
                value={address.apartment}
                onChange={(e) => handleFieldChange('apartment', e.target.value)}
              />
            </div>

            <div className="form-field">
              <label htmlFor="comment">Delivery notes (optional)</label>
              <textarea
                id="comment"
                rows={3}
                value={address.comment}
                onChange={(e) => handleFieldChange('comment', e.target.value)}
              />
            </div>
          </form>
        </section>

        {submitError && <p className="checkout__submit-error">{submitError}</p>}
      </main>

      <footer className="checkout__footer">
        <button
          type="button"
          className="pay-button"
          onClick={handlePay}
          disabled={isCartEmpty || submitting}
        >
          {submitting ? 'Processing…' : `Pay ${formatPrice(total, currency)}`}
        </button>
      </footer>
    </div>
  );
}
```

